class Solution {
  public Node insert(Node head, int insertVal) {
    Node node = new Node(insertVal);
    if (head == null) {
      node.next = node;
      return node;
    }
    Node cur = head;
    while (true) {
      boolean between = cur.val <= insertVal && insertVal <= cur.next.val;
      boolean atWrap = cur.val > cur.next.val && (insertVal >= cur.val || insertVal <= cur.next.val);
      if (between || atWrap || cur.next == head) break; // after a full loop any spot works (all equal)
      cur = cur.next;
    }
    node.next = cur.next;
    cur.next = node;
    return head;
  }
}
